using System.Globalization;using System.Windows;using System.Windows.Controls;namespace OdinVault.Manager.Wpf.Controls;public partial class ScheduleEditor:UserControl{const int TehranOffsetMinutes=210;public ScheduleEditor(){InitializeComponent();Mode.SelectedIndex=0;RefreshUi();}public string? ScheduleCron{get=>BuildCron();set=>LoadCron(value);}void Changed(object s,EventArgs e)=>RefreshUi();void RefreshUi(){if(Mode is null)return;TimePanel.Visibility=Mode.SelectedIndex==1?Visibility.Visible:Visibility.Collapsed;AdvancedPanel.Visibility=Mode.SelectedIndex==2?Visibility.Visible:Visibility.Collapsed;try{Summary.Text="زمان‌بندی: "+FormatCron(BuildCron());}catch(Exception e){Summary.Text=e.Message;}}string? BuildCron(){if(Mode.SelectedIndex==0)return null;if(Mode.SelectedIndex==2)return Normalize(Cron.Text);if(!TimeOnly.TryParseExact(Time.Text,"HH:mm",CultureInfo.InvariantCulture,DateTimeStyles.None,out var local))throw new InvalidOperationException("زمان را به شکل HH:mm وارد کنید.");var utc=Shift(local,-TehranOffsetMinutes);return $"{utc.Minute} {utc.Hour} * * *";}void LoadCron(string? cron){if(string.IsNullOrWhiteSpace(cron)){Mode.SelectedIndex=0;RefreshUi();return;}if(TryDaily(cron,out var utc)){var local=Shift(utc,TehranOffsetMinutes);Time.Text=$"{local.Hour:00}:{local.Minute:00}";Mode.SelectedIndex=1;}else{Cron.Text=cron.Trim();Mode.SelectedIndex=2;}RefreshUi();}static string? Normalize(string s){var a=s.Split(';',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries).Distinct().ToArray();return a.Length==0?null:string.Join(';',a);}static bool TryDaily(string cron,out TimeOnly t){t=default;var p=cron.Split(' ',StringSplitOptions.RemoveEmptyEntries);return !cron.Contains(';')&&p.Length==5&&p[2]=="*"&&p[3]=="*"&&p[4]=="*"&&int.TryParse(p[0],out var m)&&m is>=0 and<=59&&int.TryParse(p[1],out var h)&&h is>=0 and<=23&&(t=new TimeOnly(h,m))==t;}static TimeOnly Shift(TimeOnly t,int delta){var m=(t.Hour*60+t.Minute+delta+1440)%1440;return new(m/60,m%60);}public static string FormatCron(string? cron){if(string.IsNullOrWhiteSpace(cron))return "دستی";if(TryDaily(cron,out var utc)){var x=Shift(utc,TehranOffsetMinutes);return $"هر روز ساعت {x.Hour:00}:{x.Minute:00}";}return $"پیشرفته: {cron}";}}